/**
 * Catalog of the vendored Runeicons data: the path of one icon file and the
 * search/filter rules of the Icons workspace. Pure string work — no fetch, no
 * DOM — so the panel's behavior is unit-testable and the data stays a plain
 * module (metadata only; the SVGs live under `public/runeicons/` and are
 * fetched by id, never bundled).
 *
 * The entries are generated by `scripts/vendor-runeicons.mjs` from the
 * upstream manifest (Apache-2.0, Part 1 — see NOTICE).
 */

import {
  RUNEICON_ENTRIES,
  type RuneiconCategory,
  type RuneiconEntry,
  type RuneiconStyle,
} from './manifest';

export { RUNEICON_ENTRIES };
export type { RuneiconCategory, RuneiconEntry, RuneiconStyle };

/** The five styles, in the order the style filter shows them. */
export const RUNEICON_STYLE_IDS: readonly RuneiconStyle[] = [
  'normal',
  'duotone',
  'fill',
  'pixelated',
  'glass',
];

/** Categories in use, alphabetical; derived so the list cannot drift. */
export const RUNEICON_CATEGORY_IDS: readonly RuneiconCategory[] = Array.from(
  new Set(RUNEICON_ENTRIES.map((entry) => entry.category)),
).sort();

export type RuneiconCategoryFilter = RuneiconCategory | 'all';

export interface RuneiconFilter {
  /** Free text over name, id and tags; empty shows everything. */
  query: string;
  category: RuneiconCategoryFilter;
  style: RuneiconStyle;
}

export const DEFAULT_RUNEICON_FILTER: RuneiconFilter = {
  query: '',
  category: 'all',
  style: 'normal',
};

/**
 * Entries of the filter, in catalog order. The style filter is an
 * availability filter: an icon only shows in the styles it actually ships in
 * (the two battery icons, for example, have no `normal` file).
 */
export function filterRuneicons(
  entries: readonly RuneiconEntry[],
  filter: RuneiconFilter,
): RuneiconEntry[] {
  const needle = filter.query.trim().toLowerCase().replace(/\s+/g, ' ');

  return entries.filter((entry) => {
    if (!entry.styles.includes(filter.style)) return false;
    if (filter.category !== 'all' && entry.category !== filter.category) return false;
    if (needle === '') return true;
    if (entry.id.includes(needle)) return true;
    if (entry.name.toLowerCase().includes(needle)) return true;

    return entry.tags.some((tag) => tag.includes(needle));
  });
}

/** Path of one icon file inside `public/` (no base prefix). */
export function runeiconAssetPath(entry: RuneiconEntry, style: RuneiconStyle): string {
  // The glass set lives flat in its own `glass-icons/` directory (carried by
  // the entry's folder); every other style repeats the icon folder under the
  // style directory.
  if (style === 'glass') return `runeicons/${entry.folder}/${entry.file}`;

  return `runeicons/${style}/${entry.folder}/${entry.file}`;
}
